const casos = $('CA81P_Casos_validos').all().map(i => i.json);
const res = $input.all().map(i => i.json);
const ok = [
  r => r.permitido === false,
  r => r.registrado === true && !!r.ejecucion_id && r.auditado === false,
  r => r.registrado === true && !!r.ejecucion_id && r.auditado === true,
];
return casos.map((c, i) => {
  const r = res[i] || {};
  return { json: { caso: c.caso, esperado: c.esperado, resultado: ok[i](r) ? 'PASA' : 'FALLA', detalle: JSON.stringify(r).slice(0, 300) } };
});

const filas = $('CA81P_Evaluar_validos').all().map(i => i.json);
const r = $input.first().json;
filas.push({ caso: '4 modo inválido', esperado: 'error controlado',
  resultado: r.error ? 'PASA' : 'FALLA', detalle: JSON.stringify(r.error ?? r).slice(0, 300) });
return filas.map(f => ({ json: f }));
